// src/pages/admin/Users.js
import React, { useState, useEffect } from 'react';
import { usersAPI, clientsAPI } from '../../services/api';
import { Plus, Edit2, Trash2, ToggleLeft, ToggleRight, Users as UsersIcon, Eye, Mail, Shield, Smartphone } from 'lucide-react';

const fmtDate = (d) => d ? new Date(d).toLocaleDateString('fr-FR') : '—';
const roleBadge = (r) => {
  const map = { ADMIN: ['badge-danger', 'Admin'], LOAN_OFFICER: ['badge-info', 'Agent'], CLIENT: ['badge-success', 'Client'] };
  const [cls, label] = map[r] || ['badge-gray', r];
  return <span className={`badge ${cls}`}>{label}</span>;
};

export default function Users() {
  const [users, setUsers] = useState([]);
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState(null); // null | 'form' | 'view'
  const [selected, setSelected] = useState(null);
  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'LOAN_OFFICER', clientId: '' });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const load = async () => {
    setLoading(true);
    try {
      const [rUsers, rClients] = await Promise.all([
        usersAPI.getAll(),
        clientsAPI.getAll()
      ]);
      setUsers(rUsers.data.data);
      setClients(rClients.data.data);
    } catch {}
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const openAdd = () => { setForm({ name: '', email: '', password: '', role: 'LOAN_OFFICER', clientId: '' }); setSelected(null); setModal('form'); setError(''); };
  const openEdit = (u) => { setForm({ name: u.name, email: u.email, password: '', role: u.role, clientId: u.clientId || '' }); setSelected(u); setModal('form'); setError(''); };
  const openView = (u) => { setSelected(u); setModal('view'); };

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true); setError('');
    try {
      const data = { ...form };
      if (selected && !data.password) delete data.password;
      if (selected) await usersAPI.update(selected._id, data);
      else await usersAPI.create(data);
      setModal(null); load();
    } catch (err) { setError(err.response?.data?.message || 'Erreur'); }
    setSaving(false);
  };

  const handleToggle = async (u) => {
    try { await usersAPI.updateStatus(u._id, u.status === 'ACTIVE' ? 'INACTIVE' : 'ACTIVE'); load(); } catch {}
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Supprimer cet utilisateur ?')) return;
    try { await usersAPI.remove(id); load(); } catch (err) { alert(err.response?.data?.message || 'Erreur'); }
  };

  return (
    <div className="fade-in">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24 }}>
        <div>
          <h1 style={{ fontSize: 22, marginBottom: 4 }}>Utilisateurs</h1>
          <p style={{ color: 'var(--gray-500)', fontSize: 13 }}>{users.length} utilisateur(s)</p>
        </div>
        <button className="btn btn-primary" onClick={openAdd}><Plus size={15} /> Nouvel utilisateur</button>
      </div>

      <div className="card">
        <div className="table-wrap">
          {loading ? <div className="page-loader"><div className="spinner" /></div> : users.length === 0 ? (
            <div className="empty-state"><UsersIcon size={36} /><p>Aucun utilisateur</p></div>
          ) : (
            <table>
              <thead><tr><th>Nom</th><th>Email</th><th>Rôle</th><th>Statut</th><th>Créé le</th><th>Actions</th></tr></thead>
              <tbody>
                {users.map(u => (
                  <tr key={u._id}>
                    <td style={{ fontWeight: 500 }}>{u.name}</td>
                    <td style={{ color: 'var(--gray-500)' }}>{u.email}</td>
                    <td>{roleBadge(u.role)}</td>
                    <td>
                      <span className={`badge ${u.status === 'ACTIVE' ? 'badge-success' : 'badge-gray'}`}>
                        {u.status === 'ACTIVE' ? 'Actif' : 'Inactif'}
                      </span>
                    </td>
                    <td style={{ color: 'var(--gray-500)' }}>{fmtDate(u.createdAt)}</td>
                    <td>
                      <div style={{ display: 'flex', gap: 6 }}>
                        <button className="btn btn-outline btn-icon btn-sm" title="Voir" onClick={() => openView(u)}><Eye size={12} /></button>
                        <button className="btn btn-outline btn-icon btn-sm" title="Modifier" onClick={() => openEdit(u)}><Edit2 size={12} /></button>
                        <button className="btn btn-outline btn-icon btn-sm" onClick={() => handleToggle(u)} title={u.status === 'ACTIVE' ? 'Désactiver' : 'Activer'}>
                          {u.status === 'ACTIVE' ? <ToggleRight size={14} color="var(--success)" /> : <ToggleLeft size={14} />}
                        </button>
                        <button className="btn btn-outline btn-icon btn-sm" onClick={() => handleDelete(u._id)} style={{ color: 'var(--danger)', borderColor: '#fed7d7' }}>
                          <Trash2 size={12} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {modal === 'form' && (
        <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && setModal(null)}>
          <div className="modal fade-in">
            <div className="modal-header">
              <h3>{selected ? 'Modifier' : 'Nouvel'} utilisateur</h3>
              <button onClick={() => setModal(null)} className="btn btn-icon btn-outline" style={{ fontSize: 16 }}>✕</button>
            </div>
            <form onSubmit={handleSave}>
              <div className="modal-body">
                {error && <div className="alert alert-danger">{error}</div>}
                <div className="form-group"><label>Nom *</label>
                  <input className="form-control" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required /></div>
                <div className="form-group"><label>Email *</label>
                  <input className="form-control" type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} required /></div>
                <div className="form-group"><label>{selected ? 'Nouveau mot de passe (laisser vide = inchangé)' : 'Mot de passe *'}</label>
                  <input className="form-control" type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} required={!selected} /></div>
                <div className="form-group"><label>Rôle *</label>
                  <select className="form-control" value={form.role} onChange={e => {
                    const role = e.target.value;
                    setForm({ ...form, role, clientId: role !== 'CLIENT' ? '' : form.clientId });
                  }}>
                    <option value="ADMIN">Administrateur</option>
                    <option value="LOAN_OFFICER">Agent de crédit</option>
                    <option value="CLIENT">Client</option>
                  </select>
                </div>
                {form.role === 'CLIENT' && (
                  <div className="form-group" style={{ marginBottom: 0 }}><label>Client associé *</label>
                    <select className="form-control" value={form.clientId} onChange={e => setForm({ ...form, clientId: e.target.value })} required>
                      <option value="">-- Sélectionnez le client --</option>
                      {clients.map(c => (
                        <option key={c._id} value={c._id}>{c.name} ({c.phone})</option>
                      ))}
                    </select>
                  </div>
                )}
              </div>
              <div className="modal-footer">
                <button type="button" onClick={() => setModal(null)} className="btn btn-outline">Annuler</button>
                <button type="submit" className="btn btn-primary" disabled={saving}>{saving ? 'Enregistrement...' : 'Enregistrer'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {modal === 'view' && selected && (
        <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && setModal(null)}>
          <div className="modal fade-in" style={{ maxWidth: 400 }}>
            <div className="modal-header">
              <h3>Détails de l'utilisateur</h3>
              <button onClick={() => setModal(null)} className="btn btn-icon btn-outline">✕</button>
            </div>
            <div className="modal-body">
              <div style={{ textAlign: 'center', marginBottom: 20 }}>
                <div style={{ width: 60, height: 60, borderRadius: '50%', background: 'var(--primary-subtle)', color: 'var(--primary)', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: 24, fontWeight: 700, marginBottom: 12 }}>
                  {selected.name?.slice(0, 1).toUpperCase()}
                </div>
                <h4 style={{ fontSize: 18, marginBottom: 4 }}>{selected.name}</h4>
                {roleBadge(selected.role)}
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 12, padding: 16, background: 'var(--gray-50)', borderRadius: 10 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <Mail size={16} color="var(--gray-400)" />
                  <span style={{ fontSize: 13 }}>{selected.email}</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <Shield size={16} color="var(--gray-400)" />
                  <span style={{ fontSize: 13, textTransform: 'capitalize' }}>Statut: <strong>{selected.status.toLowerCase()}</strong></span>
                </div>
                {selected.clientId && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <Smartphone size={16} color="var(--gray-400)" />
                    <span style={{ fontSize: 13 }}>ID Client associé: <code style={{ fontSize: 11 }}>{selected.clientId}</code></span>
                  </div>
                )}
                <div style={{ fontSize: 11, color: 'var(--gray-400)', marginTop: 8, borderTop: '1px solid var(--gray-200)', paddingTop: 8 }}>
                  Créé le {fmtDate(selected.createdAt)}
                </div>
              </div>
            </div>
            <div className="modal-footer">
              <button onClick={() => setModal(null)} className="btn btn-outline btn-block">Fermer</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
